import { MeshStandardNodeMaterial, Group, Mesh, PlaneGeometry, CylinderGeometry, AmbientLight, DirectionalLight, Color } from 'three/webgpu';
import { color, vec3, mix, uv, positionLocal, output } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { THREE } = ctx;
  const mainGroup = new Group();

  const colors = config.intent?.visualSpec?.colors ?? {
    background: "#0b0b10",
    surface: "#16161d",
    ink: "#16161d",
    paper: "#e8ecf2",
    accent: "#ff2a38",
    gradientStops: [{ at: 0, hex: "#191921" }, { at: 1, hex: "#121218" }]
  };

  const backdropGeo = new PlaneGeometry(8, 6.5);
  const backdropMat = new MeshStandardNodeMaterial({
    roughness: 0.9,
    metalness: 0.1,
  });

  const stop0 = color(colors.gradientStops[0]?.hex ?? "#191921");
  const stop1 = color(colors.gradientStops[1]?.hex ?? "#121218");
  backdropMat.colorNode = mix(stop1, stop0, uv().y);

  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  backdropMesh.position.z = -0.5;
  mainGroup.add(backdropMesh);

  const subKeyLight = new DirectionalLight(colors.accent, 0.8);
  subKeyLight.position.set(-3, 4, 3);
  mainGroup.add(subKeyLight);

  const localAmbient = new AmbientLight(colors.paper, 0.25);
  mainGroup.add(localAmbient);

  const cardWidth = 1.5;
  const cardHeight = 1.9;
  const cardGap = 0.25;
  const totalCards = 3;
  const startX = -((totalCards - 1) * (cardWidth + cardGap)) / 2;

  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const cardsData = [];
  for (let i = 0; i < totalCards; i++) {
    const rawGlyph = textItems[i * 3 + 0]?.text ?? `0${i + 1}`;
    const rawTitle = textItems[i * 3 + 1]?.text ?? "Feature";
    const rawBody = textItems[i * 3 + 2]?.text ?? "Description";
    cardsData.push({ glyph: rawGlyph, title: rawTitle, body: rawBody });
  }

  const activeTimelines = [];

  cardsData.forEach((data, index) => {
    const cardContainer = new Group();
    cardContainer.position.set(startX + index * (cardWidth + cardGap), 0, 0);
    mainGroup.add(cardContainer);

    const shadowGeo = new PlaneGeometry(cardWidth * 1.1, cardHeight * 1.1);
    const shadowMat = new MeshStandardNodeMaterial({
      color: 0x010103,
      transparent: true,
      opacity: 0.45,
      roughness: 1.0,
      metalness: 0.0
    });
    const shadowMesh = new Mesh(shadowGeo, shadowMat);
    shadowMesh.position.set(0, -0.05, -0.02);
    cardContainer.add(shadowMesh);

    const cardBaseGeo = new PlaneGeometry(cardWidth, cardHeight);
    const cardBaseMat = new MeshStandardNodeMaterial({
      roughness: 0.6,
      metalness: 0.25,
      clearcoat: 0.15
    });
    const cardTopColor = color("#191921");
    const cardBottomColor = color("#121218");
    cardBaseMat.colorNode = mix(cardBottomColor, cardTopColor, uv().y);

    const cardBaseMesh = new Mesh(cardBaseGeo, cardBaseMat);
    cardContainer.add(cardBaseMesh);

    const discGeo = new CylinderGeometry(0.2, 0.2, 0.05, 32);
    discGeo.rotateX(Math.PI / 2);
    const discMat = new MeshStandardNodeMaterial({
      color: colors.surface,
      roughness: 0.55,
      metalness: 0.5,
      clearcoat: 0.2
    });
    const discMesh = new Mesh(discGeo, discMat);
    discMesh.position.set(0, 0.45, 0.025);
    cardContainer.add(discMesh);

    const glyphText = ctx.fontAtlas.createText(data.glyph, {
      fontSize: 20,
      color: colors.accent,
      align: 'center'
    });
    glyphText.position.set(0, 0.45, 0.055);
    cardContainer.add(glyphText);

    const titleText = ctx.fontAtlas.createText(data.title, {
      fontSize: 20,
      color: colors.paper,
      align: 'center',
      maxWidthPx: cardWidth * 180
    });
    titleText.position.set(0, 0.05, 0.01);
    cardContainer.add(titleText);

    const bodyText = ctx.fontAtlas.createText(data.body, {
      fontSize: 13,
      color: colors.paper,
      align: 'center',
      maxWidthPx: (cardWidth - 0.2) * 180
    });
    bodyText.position.set(0, -0.35, 0.01);
    cardContainer.add(bodyText);

    cardContainer.position.y += 0.2;
    cardContainer.scale.set(0.001, 0.001, 0.001);

    const entryTl = gsap.timeline({ delay: index * 0.08 });
    entryTl.to(cardContainer.position, { y: 0, duration: 0.5, ease: "power2.out" });
    entryTl.to(cardContainer.scale, { x: 1, y: 1, z: 1, duration: 0.5, ease: "power2.out" }, "<");
    activeTimelines.push(entryTl);

    let hoverTl = null;
    const handlers = {
      onPointerEnter: () => {
        if (hoverTl) hoverTl.kill();
        hoverTl = gsap.timeline();
        hoverTl.to(cardBaseMesh.position, { y: 0.06, z: 0.12, duration: 0.18, ease: "power2.out" });
        hoverTl.to(discMesh.position, { y: 0.51, z: 0.145, duration: 0.18, ease: "power2.out" }, "<");
        hoverTl.to(glyphText.position, { y: 0.51, z: 0.175, duration: 0.18, ease: "power2.out" }, "<");
        hoverTl.to(titleText.position, { y: 0.11, z: 0.13, duration: 0.18, ease: "power2.out" }, "<");
        hoverTl.to(bodyText.position, { y: -0.29, z: 0.13, duration: 0.18, ease: "power2.out" }, "<");
        hoverTl.to(shadowMesh.scale, { x: 1.15, y: 1.15, duration: 0.18, ease: "power2.out" }, "<");
        hoverTl.to(shadowMat, { opacity: 0.25, duration: 0.18, ease: "power2.out" }, "<");
      },
      onPointerLeave: () => {
        if (hoverTl) hoverTl.kill();
        hoverTl = gsap.timeline();
        hoverTl.to(cardBaseMesh.position, { x: 0, y: 0, z: 0, duration: 0.18, ease: "power2.out" });
        hoverTl.to(discMesh.position, { y: 0.45, z: 0.025, duration: 0.18, ease: "power2.out" }, "<");
        hoverTl.to(glyphText.position, { y: 0.45, z: 0.055, duration: 0.18, ease: "power2.out" }, "<");
        hoverTl.to(titleText.position, { y: 0.05, z: 0.01, duration: 0.18, ease: "power2.out" }, "<");
        hoverTl.to(bodyText.position, { y: -0.35, z: 0.01, duration: 0.18, ease: "power2.out" }, "<");
        hoverTl.to(shadowMesh.scale, { x: 1, y: 1, duration: 0.18, ease: "power2.out" }, "<");
        hoverTl.to(shadowMat, { opacity: 0.45, duration: 0.18, ease: "power2.out" }, "<");
      }
    };

    cardContainer.userData.handlers = handlers;
  });

  mainGroup.userData.cleanup = () => {
    activeTimelines.forEach(tl => tl.kill());
    backdropGeo.dispose();
    backdropMat.dispose();
    discGeo.dispose();
    discMat.dispose();
  };

  return mainGroup;
}
